SELECT analytics_order_facts.quarter, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year IN (2022, 2023) AND analytics_order_facts.region = 'West' AND analytics_order_facts.channel = 'retail' AND analytics_order_facts.customer_segment = 'small_business' GROUP BY analytics_order_facts.quarter ORDER BY analytics_order_facts.quarter ASC LIMIT 24
